insert into public.words (slug, word, pronunciation, part_of_speech, definition, plain_english, examples, synonyms, antonyms, difficulty, gre_frequency, etymology, etymology_status, secondary_meanings)
select v.slug, v.slug, v.pr, case v.pos when 'n' then 'noun' when 'v' then 'verb' when 'a' then 'adjective' else 'adverb' end, v.def,
  coalesce(v.plain, initcap(v.slug) || ' means ' || lower(left(v.def,1)) || substr(v.def,2)),
  v.ex::text[], v.syn::text[], v.ant::text[], (v.df / 10)::smallint, (v.df % 10)::smallint, v.ety,
  case v.es when 'e' then 'established' when 'u' then 'uncertain' else 'none' end, v.sec::text[]
from (values
('metamorphic','met-uh-MOR-fik','a','Produced by transformation, especially geological change under heat or pressure.',NULL,'{"The valley contains extensive metamorphic rock.","The geologist traced the region''s metamorphic history."}','{"transformed","altered"}','{}',22,'From metamorphosis and Greek metamorphoun (transform), combining meta- (change) and morphe (form), with -ic.','e','{}'),
('metamorphose','met-uh-MOR-fohz','v','To transform profoundly in form or character.',NULL,'{"Economic pressure can metamorphose a local movement into a national coalition.","The insect will metamorphose before reproducing."}','{"transform","transfigure"}','{}',22,'Through French from Greek metamorphoun (transform), combining meta- and morphe (form); the verb was influenced by metamorphosis.','e','{}'),
('polymorphism','pol-ee-MOR-fiz-um','n','The occurrence of distinct forms within a species, substance, or system.',NULL,'{"Genetic polymorphism helps explain variation within the population.","The chemist investigated polymorphism in the crystalline compound."}','{"multiple forms","form variation"}','{}',22,'From Greek polymorphos (many-shaped), combining polys (many) and morphe (form), with -ism.','e','{}'),
('polymorphic','pol-ee-MOR-fik','a','Occurring in several distinct forms.',NULL,'{"The polymorphic species challenged older classification schemes.","A polymorphic mineral may crystallize in several structures."}','{"multiform","variable"}','{}',22,'From Greek polymorphos (many-shaped), combining polys (many) and morphe (form), with -ic.','e','{}'),
('anthropomorphic','an-thruh-puh-MOR-fik','a','Attributing human form or characteristics to nonhuman things.',NULL,'{"The fable''s anthropomorphic animals debate questions of justice.","The researcher warned against anthropomorphic interpretations of insect behavior."}','{"humanlike","humanized"}','{}',22,'From Greek anthropomorphos (human-shaped), combining anthropos (human) and morphe (form), with -ic.','e','{}'),
('anthropomorphism','an-thruh-puh-MOR-fiz-um','n','The attribution of human traits to nonhuman beings or things.',NULL,'{"Anthropomorphism can make animal stories engaging but scientifically misleading.","The theologian criticized anthropomorphism in descriptions of divine intention."}','{"humanization","personification"}','{}',22,'From Greek anthropomorphos (human-shaped), combining anthropos and morphe, with -ism.','e','{}'),
('zoomorphic','zoh-uh-MOR-fik','a','Having or representing an animal''s form.',NULL,'{"The excavation uncovered several zoomorphic vessels.","Zoomorphic decoration linked the palace to regional religious traditions."}','{"animal-shaped","animal-like"}','{}',22,'From Greek zoion (animal) and morphe (form), with -ic.','e','{}'),
('isomorphic','eye-suh-MOR-fik','a','Having corresponding structures despite differences in appearance or material.',NULL,'{"The mathematician proved that the two groups were isomorphic.","The models are isomorphic only under restrictive assumptions."}','{"structurally equivalent","corresponding"}','{}',22,'From Greek isos (equal) and morphe (form), with -ic, through scientific terminology.','e','{}'),
('chronology','kruh-NOL-uh-jee','n','The arrangement or study of events in their temporal order.',NULL,'{"The letters established a reliable chronology of the expedition.","Her argument depends on a disputed chronology."}','{"timeline","event sequence"}','{}',22,'From Greek chronos (time) and -logia (study), through learned Latin chronology formations.','e','{}'),
('chronological','kron-uh-LOJ-ih-kul','a','Arranged according to the order in which events occurred.',NULL,'{"The archive organizes correspondence in chronological order.","A chronological account can obscure important thematic connections."}','{"sequential","time-ordered"}','{}',22,'From chronology with -ical, ultimately Greek chronos (time) and -logia (study).','e','{}'),
('anachronistic','uh-nak-ruh-NIS-tik','a','Belonging to a different historical period from its surrounding context.',NULL,'{"The costume''s zipper was conspicuously anachronistic.","Critics called the institution''s hereditary privileges anachronistic."}','{"outdated","temporally misplaced"}','{"contemporary"}',22,'From anachronism with -istic, ultimately Greek ana- (back) and chronos (time).','e','{}'),
('synchronize','SING-kruh-nyz','v','To make events or processes occur at coordinated times.',NULL,'{"The technicians must synchronize the recording devices.","The agreement sought to synchronize inspections across national borders."}','{"coordinate","align"}','{"desynchronize"}',22,'From Greek synchronos (contemporary), combining syn- (together) and chronos (time), with -ize.','e','{}'),
('synchronous','SING-kruh-nus','a','Occurring at the same time or in a coordinated temporal pattern.',NULL,'{"The instruments recorded synchronous changes in pressure.","Synchronous instruction requires students to attend at a fixed time."}','{"simultaneous","coincident"}','{"asynchronous"}',22,'From Greek synchronos (occurring together), combining syn- and chronos, with English -ous.','e','{}'),
('asynchronous','ay-SING-kruh-nus','a','Not occurring simultaneously or according to a shared timing pattern.',NULL,'{"Asynchronous discussion allows participants to respond at different times.","The system tolerates asynchronous signals from its sensors."}','{"nonsimultaneous","unsynchronized"}','{"synchronous"}',22,'Formed with Greek privative a- and synchronous, ultimately syn- and chronos (time).','e','{}'),
('synchronism','SING-kruh-niz-um','n','Coincidence in time or correspondence between events in different historical sequences.',NULL,'{"The synchronism of the two revolts suggested coordination.","A documented synchronism helped establish the ruler''s dates."}','{"simultaneity","temporal coincidence"}','{}',22,'From Greek synchronismos, ultimately syn- (together) and chronos (time), with -ismos.','e','{}'),
('chronicle','KRON-ih-kul','n','A factual account of events arranged in temporal sequence.',NULL,'{"The chronicle records several otherwise unknown diplomatic missions.","Its reputation as a reliable chronicle remains disputed."}','{"record","annals"}','{}',22,'Through French and Latin chronica from Greek chronika (annals), ultimately chronos (time); the final spelling is historically remodeled.','e','{}'),
('chronometer','kruh-NOM-ih-ter','n','A highly accurate instrument for measuring time.',NULL,'{"The navigator checked the chronometer before calculating longitude.","A faulty chronometer could imperil an entire voyage."}','{"timepiece","precision clock"}','{}',22,'From Greek chronos (time) and metron (measure), through learned European coinage.','e','{}'),
('chronometric','kron-uh-MET-rik','a','Relating to precise measurement of time.',NULL,'{"Chronometric measurements revealed a slight delay in processing.","The laboratory compared several chronometric techniques."}','{"time-measuring","temporal-measuring"}','{}',31,'From chronometry, combining Greek chronos (time) and metron (measure), with -ic.','e','{}'),
('diachronic','dy-uh-KRON-ik','a','Examining change across time rather than at one moment.',NULL,'{"A diachronic analysis traced the word''s changing meanings.","The study adopts a diachronic approach to constitutional interpretation."}','{"historical","time-spanning"}','{"synchronic"}',22,'From Greek dia- (through) and chronos (time), with -ic, in modern linguistic terminology.','e','{}'),
('synchronic','sin-KRON-ik','a','Examining a system at a particular time rather than across its history.',NULL,'{"The linguist offered a synchronic description of the dialect.","Synchronic comparison cannot by itself explain historical development."}','{"cross-sectional","contemporaneous"}','{"diachronic"}',22,'From Greek syn- (together) and chronos (time), with -ic, specialized in modern linguistics.','e','{}'),
('philanthropy','fih-LAN-thruh-pee','n','Efforts to promote human welfare, especially through charitable giving.',NULL,'{"Private philanthropy financed the hospital''s new research wing.","The historian examined the political assumptions underlying elite philanthropy."}','{"charity","benevolence"}','{"misanthropy"}',22,'From Greek philanthropia (love of humanity), combining philos (loving) and anthropos (human), with -ia.','e','{}'),
('philanthropic','fil-un-THROP-ik','a','Seeking to improve human welfare through generosity or charitable action.',NULL,'{"The foundation redirected its philanthropic efforts toward public health.","A philanthropic motive does not guarantee an effective intervention."}','{"charitable","benevolent"}','{"misanthropic"}',22,'From philanthropy and -ic, ultimately Greek philos (loving) and anthropos (human).','e','{}'),
('philosophy','fih-LOS-uh-fee','n','Systematic inquiry into knowledge, existence, value, and reasoning.',NULL,'{"Her philosophy emphasizes obligations to future generations.","Philosophy can clarify assumptions that empirical research leaves unexamined."}','{"thought","worldview"}','{}',22,'From Greek philosophia (love of wisdom), combining philos (loving) and sophia (wisdom).','e','{}'),
('philosopher','fih-LOS-uh-fer','n','A thinker who investigates fundamental questions about knowledge, reality, or value.',NULL,'{"The philosopher challenged the presumed distinction between nature and culture.","A philosopher need not withdraw from practical political debate."}','{"thinker","theorist"}','{}',22,'From Anglo-French philosophe with an English agent ending, ultimately Greek philosophos (loving wisdom).','e','{}'),
('philosophical','fil-uh-SOF-ih-kul','a','Relating to fundamental inquiry or showing thoughtful acceptance of difficulties.',NULL,'{"The dispute rests on a philosophical disagreement about freedom.","She remained philosophical about the project''s unexpected cancellation."}','{"reflective","contemplative"}','{"unreflective"}',22,'From Latin philosophicus and English -al, ultimately Greek philosophikos, from philos (loving) and sophia (wisdom).','e','{}'),
('philology','fih-LOL-uh-jee','n','The historical study of language through written texts.',NULL,'{"Philology supplied evidence for the manuscript''s regional origin.","Her training in philology sharpened her attention to linguistic change."}','{"historical linguistics","textual scholarship"}','{}',22,'From Greek philologia (love of learning or discourse), combining philos (loving) and logos (word or account).','e','{}'),
('philologist','fih-LOL-uh-jist','n','A scholar studying language historically through texts.',NULL,'{"The philologist identified a previously unnoticed scribal error.","A philologist reconstructed the poem''s earlier wording."}','{"historical linguist","textual scholar"}','{}',22,'Formed from philology with -ist, ultimately Greek philos (loving) and logos (word).','e','{}'),
('philological','fil-uh-LOJ-ih-kul','a','Relating to historical or textual study of language.',NULL,'{"Philological evidence challenged the traditional attribution.","The edition includes an extensive philological commentary."}','{"linguistic","textual"}','{}',22,'From philology with -ical, ultimately Greek philos (loving) and logos (word).','e','{}'),
('philatelist','fih-LAT-uh-list','n','A collector or student of postage stamps and postal history.',NULL,'{"The philatelist authenticated the rare colonial stamp.","A philatelist used postal markings to reconstruct the letter''s route."}','{"stamp collector","stamp specialist"}','{}',22,'From philately with -ist; French philatelie combines Greek philos (loving) and ateleia (exemption from payment), referring to prepaid postage.','e','{}'),
('bibliophile','BIB-lee-uh-fyle','n','A person who loves or collects books.',NULL,'{"The bibliophile valued marginal notes as much as pristine bindings.","A local bibliophile donated the collection to the university."}','{"book lover","book collector"}','{}',22,'From French bibliophile, combining Greek biblion (book) and philos (loving).','e','{}'),
('anglophile','ANG-gluh-fyle','n','A person strongly attracted to England or English culture.',NULL,'{"An enthusiastic anglophile, she specialized in English architectural history.","The novelist''s anglophile tastes shaped his descriptions of country life."}','{"England admirer","English-culture enthusiast"}','{}',22,'Formed from Anglo- (English) and -phile, from Greek philos (loving).','e','{}'),
('francophile','FRANG-kuh-fyle','n','A person strongly attracted to France or French culture.',NULL,'{"The francophile translated several neglected French essayists.","Her francophile preferences did not prevent criticism of French colonial policy."}','{"France admirer","French-culture enthusiast"}','{}',21,'Formed from Franco- (French) and -phile, from Greek philos (loving).','e','{}'),
('philately','fih-LAT-uh-lee','n','The collection and study of postage stamps and postal history.',NULL,'{"Philately can illuminate changes in national identity.","The exhibition explored the diplomatic history preserved through philately."}','{"stamp collecting","postal study"}','{}',21,'From French philatelie, coined from Greek philos (loving) and ateleia (exemption from payment), alluding to prepaid postage.','e','{}'),
('anthropology','an-thruh-POL-uh-jee','n','The study of human societies, cultures, origins, and biological development.',NULL,'{"Anthropology challenged several assumptions underlying the development program.","Her research connects anthropology with environmental history."}','{"human science","cultural study"}','{}',22,'From Greek anthropos (human) and -logia (study), through learned European formations.','e','{}'),
('anthropologist','an-thruh-POL-uh-jist','n','A scholar studying human societies, cultures, or biological development.',NULL,'{"The anthropologist conducted fieldwork in three coastal communities.","An anthropologist cautioned against treating the community as culturally uniform."}','{"human scientist","ethnographer"}','{}',22,'Formed from anthropology with -ist, ultimately Greek anthropos (human) and logos (account).','e','{}'),
('anthropological','an-thruh-puh-LOJ-ih-kul','a','Relating to the study of humans and their societies or development.',NULL,'{"Anthropological evidence complicated the government''s account of customary law.","The museum reconsidered its anthropological displays after public consultation."}','{"ethnographic","human-scientific"}','{}',22,'From anthropology with -ical, ultimately Greek anthropos (human) and -logia (study).','e','{}'),
('anthropocentric','an-thruh-poh-SEN-trik','a','Treating human interests or perspectives as centrally important.',NULL,'{"The essay criticizes anthropocentric assumptions in environmental policy.","An anthropocentric framework may overlook the interests of other species."}','{"human-centered","human-focused"}','{"ecocentric"}',22,'Formed from Greek anthropos (human) and kentron (center), with -ic.','e','{}'),
('anthropocentrism','an-thruh-poh-SEN-triz-um','n','The view that humans are central or uniquely significant.',NULL,'{"The philosopher argued that anthropocentrism distorts environmental ethics.","The exhibit challenged the anthropocentrism of earlier natural histories."}','{"human-centeredness","human exceptionalism"}','{"ecocentrism"}',22,'Formed from anthropocentric with -ism replacing -ic, ultimately Greek anthropos (human) and kentron (center).','e','{}'),
('anthropometry','an-thruh-POM-uh-tree','n','The systematic measurement of human bodies.',NULL,'{"Anthropometry informed the design of safer workstations.","Historical abuses of anthropometry demand careful ethical scrutiny."}','{"body measurement","human measurement"}','{}',22,'From Greek anthropos (human) and metron (measure), with a learned noun ending.','e','{}'),
('misanthropic','mis-un-THROP-ik','a','Distrustful or contemptuous of humanity.',NULL,'{"The novel''s misanthropic narrator distrusts every apparent act of kindness.","Isolation gradually hardened his skepticism into a misanthropic worldview."}','{"human-hating","cynical"}','{"philanthropic"}',22,'From Greek misanthropos (hating humanity), combining misos (hatred) and anthropos (human), with -ic.','e','{}'),
('misanthropy','mis-AN-thruh-pee','n','A general dislike or distrust of humanity.',NULL,'{"His satire expresses disappointment rather than unqualified misanthropy.","The essay traces her misanthropy to repeated political betrayals."}','{"human-hatred","cynicism"}','{"philanthropy"}',22,'From Greek misanthropia, combining misos (hatred) and anthropos (human), with -ia.','e','{}'),
('predict','prih-DIKT','v','To state what is likely to happen in the future.',NULL,'{"The model failed to predict the sudden decline.","Past performance cannot reliably predict every future outcome."}','{"forecast","foretell"}','{}',22,'From Latin praedicere (say beforehand), combining prae- (before) and dicere (say).','e','{}'),
('contradict','kon-truh-DIKT','v','To deny a statement or be inconsistent with it.',NULL,'{"The newly discovered letters contradict the official account.","Two credible witnesses can contradict each other without deliberate deception."}','{"refute","oppose"}','{"confirm","corroborate"}',22,'From Latin contradicere (speak against), combining contra- (against) and dicere (say).','e','{}'),
('verdict','VER-dikt','n','A formal decision or judgment, especially by a jury.',NULL,'{"The jury returned a unanimous verdict.","Public opinion delivered its verdict before the inquiry concluded."}','{"judgment","decision"}','{}',22,'From Anglo-French verdit (true saying), combining ver (true), from Latin verus, and dit (said), from dicere.','e','{}'),
('indict','in-DYTE','v','To charge formally with a serious crime.',NULL,'{"The grand jury voted to indict the former treasurer.","The prosecutor lacked sufficient evidence to indict either official."}','{"charge","accuse"}','{"exonerate"}',22,'From Anglo-French enditer (accuse), ultimately Latin indictare, from in- and dictare, frequentative of dicere; English spelling restored ct.','e','{}'),
('dictate','DIK-tayt','v','To prescribe authoritatively or determine what must happen.',NULL,'{"Financial constraints dictate the pace of construction.","No single donor should dictate the institution''s research priorities."}','{"command","prescribe"}','{"request"}',22,'From Latin dictare (say repeatedly or prescribe), a frequentative of dicere (say).','e','{}'),
('interdict','in-ter-DIKT','v','To prohibit or obstruct by authoritative action.',NULL,'{"The court may interdict activities that threaten public safety.","Naval forces sought to interdict shipments to the besieged port."}','{"prohibit","ban"}','{"permit","authorize"}',22,'From Latin interdicere (forbid), combining inter- (between) and dicere (say).','e','{}'),
('jurisdiction','joor-is-DIK-shun','n','The legal authority to hear cases or govern a particular area.',NULL,'{"The court declined jurisdiction over the foreign dispute.","Several agencies claimed overlapping jurisdiction in the matter."}','{"authority","legal competence"}','{}',22,'From Latin iurisdictio, combining ius, iuris (law) and dictio (a saying), from dicere (say).','e','{}'),
('valediction','val-ih-DIK-shun','n','An expression or speech of farewell.',NULL,'{"Her valediction emphasized gratitude rather than regret.","The poem transforms a private valediction into a meditation on separation."}','{"farewell","leave-taking"}','{"greeting"}',22,'From Latin valedicere (say farewell), combining vale (be well) and dicere (say), with an action-noun ending.','e','{}'),
('dictum','DIK-tum','n','An authoritative statement or concise expression of principle.',NULL,'{"The judge''s dictum influenced later interpretations of the statute.","She challenged the familiar dictum that markets always correct themselves."}','{"pronouncement","maxim"}','{}',22,'Borrowed from Latin dictum (something said), the neuter participle of dicere (say); -um is a Latin inflection.','e','{}'),
('dictatorial','dik-tuh-TOR-ee-ul','a','Exercising authority in an oppressive or domineering manner.',NULL,'{"His dictatorial management style drove experienced staff away.","The emergency decree granted the president nearly dictatorial powers."}','{"autocratic","authoritarian"}','{"democratic","consultative"}',22,'From dictator, Latin dictator (one who dictates), from dictare, frequentative of dicere, with relational endings.','e','{}'),
('prediction','prih-DIK-shun','n','A statement about what is expected to happen.',NULL,'{"The prediction rested on assumptions that later proved false.","A precise prediction permits a more rigorous test."}','{"forecast","prognosis"}','{}',22,'From Latin praedictio, from praedicere (say beforehand), combining prae-, dicere, and an action-noun ending.','e','{}'),
('contradiction','kon-truh-DIK-shun','n','A conflict between statements or facts that cannot all be true.',NULL,'{"The testimony contains a serious internal contradiction.","The policy exposes a contradiction between public commitments and private incentives."}','{"inconsistency","incompatibility"}','{"consistency","agreement"}',22,'From Latin contradictio, from contradicere (speak against), combining contra- and dicere.','e','{}'),
('prologue','PROH-lawg','n','An introductory section preceding a literary work or event.','It sets things up before the main work begins.','{"The prologue establishes the rivalry that drives the novel.","Her conciliatory remarks served as a prologue to negotiations."}','{"introduction","preface"}','{}',22,'From Greek prologos, from pro- "before" and logos "speech."','e','{}'),
('epilogue','EP-uh-lawg','n','A concluding section that follows the main work.','It tells you what happens after the main story ends.','{"The epilogue reveals the consequences of the minister’s deception.","An uneasy reconciliation forms the novel’s epilogue."}','{"afterword","conclusion"}','{}',22,'From Greek epilogos, a concluding speech, from epi- "upon, in addition" and logos "speech."','e','{}'),
('dialogue','DYE-uh-lawg','n','An exchange of ideas between two or more participants.','People talk with one another rather than past one another.','{"The commission encouraged dialogue between rival factions.","Genuine dialogue requires more than alternating prepared statements."}','{"conversation","discussion"}','{}',22,'From Greek dialogos, related to dialegesthai "converse," from dia- "through, between" and legein "speak."','e','{}'),
('monologue','MON-uh-lawg','n','An extended speech delivered by one person.','One person does all the talking for a while.','{"The interview deteriorated into a monologue about the candidate’s achievements.","Her dramatic monologue exposes the narrator’s self-deception."}','{"soliloquy","speech"}','{}',22,'From Greek monologos "speaking alone," combining monos "alone" and logos "speech."','e','{}'),
('analogy','uh-NAL-uh-jee','n','A comparison that explains something through a relevant similarity.',NULL,'{"The constitutional analogy clarifies the limits of executive power.","Her analogy illuminates the problem without proving the conclusion."}','{"comparison","parallel"}','{}',22,'From Greek analogia "proportion," from ana- and logos "ratio, account." It is not simply "similar speech."','e','{}'),
('logic','LOJ-ik','n','The principles governing valid inference and consistent reasoning.','It concerns whether your conclusions really follow from your reasons.','{"The argument’s emotional appeal conceals its defective logic.","She accepted the evidence but questioned the logic of his inference."}','{"reasoning","rationality"}','{}',22,'Through Latin logica from Greek logikē, the art of reasoning, related to logos "reason, account" and the adjective ending -ikos.','e','{}'),
('logical','LOJ-ih-kul','a','Consistent with sound reasoning or valid inference.','The reasoning makes sense and hangs together.','{"A logical objection need not be a persuasive political slogan.","Her conclusion is logical only if the initial assumption holds."}','{"rational","coherent"}','{"illogical","irrational"}',22,'From logic with adjectival -al; logic ultimately reflects Greek logos and -ikos.','e','{}'),
('illogical','ih-LOJ-ih-kul','a','Inconsistent with sound reasoning.','The conclusion does not make sense from the stated reasons.','{"It is illogical to treat correlation as proof of causation.","His resentment was understandable, but his accusation was illogical."}','{"irrational","incoherent"}','{"logical","rational"}',22,'From negative il-, an assimilated form of Latin in-, and logical, ultimately from Greek logos.','e','{}'),
('neologism','nee-OL-uh-jiz-um','n','A newly coined word or expression.','It is a word someone has recently invented.','{"The critic dismissed the neologism as an unnecessary substitute for a familiar word.","A successful neologism can outlive the controversy surrounding its invention."}','{"coinage","new term"}','{}',22,'From French néologisme, combining Greek neos "new," logos "word," and -ism.','e','{}'),
('apology','uh-POL-uh-jee','n','An expression of regret for a fault or injury.',NULL,'{"His apology acknowledged the error without minimizing its consequences.","The philosopher’s apology defended a position rather than expressing remorse."}','{"expression of regret","defense"}','{}',22,'From Greek apologia "speech in defense," from apo- "away" and logos "speech." Its defensive sense preceded the modern expression of regret.','e','{"A formal defense of a belief or position."}'),
('apologize','uh-POL-uh-jyze','v','To express regret for a fault or injury.',NULL,'{"The editor agreed to apologize for the misleading headline.","He refused to apologize merely for questioning the prevailing theory."}','{"express regret","make amends"}','{}',22,'From apology and -ize, ultimately Greek apologia "speech in defense."','e','{}'),
('eulogize','YOO-luh-jyze','v','To praise someone or something highly, especially in a memorial speech.',NULL,'{"Former rivals gathered to eulogize the principled reformer.","The essay eulogizes an institution whose actual record was mixed."}','{"praise","extol"}','{"denigrate","vilify"}',22,'From eulogy and -ize, ultimately Greek eulogia "praise," from eu- "well" and logos "speech."','e','{}'),
('tautology','taw-TOL-uh-jee','n','An unnecessary repetition of the same idea in different words.',NULL,'{"The phrase \"a unanimous consensus\" invites criticism as a tautology.","Calling every successful policy effective risks tautology rather than analysis."}','{"redundancy","repetition"}','{}',22,'From Greek tautologia, from tautologos "repeating the same," combining tauto- "the same" and logos "speech."','e','{"A statement true under every interpretation in formal logic."}'),
('trilogy','TRIL-uh-jee','n','A group of three related literary or artistic works.','It is a connected set of three works.','{"The trilogy traces a family’s fortunes across three political regimes.","Each volume of the trilogy can be read independently."}','{"three-part series","triad"}','{}',21,'From Greek trilogia, a group of three dramas, combining tri- "three" and logos "discourse."','e','{}'),
('analogue','AN-uh-lawg','n','Something comparable to another in significant respects.','It is a counterpart that resembles something in an important way.','{"The historian sought a classical analogue for the modern crisis.","No exact analogue exists for this unusual legal arrangement."}','{"counterpart","parallel"}','{}',22,'From French analogue, ultimately Greek analogos "proportionate," from ana- and logos "ratio."','e','{}'),
('concur','kun-KUR','v','To agree or occur at the same time.',NULL,'{"Several independent witnesses concur on the essential facts.","Economic and political pressures concurred to undermine the reform."}','{"agree","coincide"}','{"disagree","dissent"}',22,'From Latin concurrere "run together," from con- "together" and currere "run."','e','{}'),
('incur','in-KUR','v','To bring an undesirable consequence or obligation upon oneself.',NULL,'{"The agency may incur substantial costs by delaying repairs.","His public dissent incurred the displeasure of senior officials."}','{"invite","sustain"}','{}',22,'From Latin incurrere "run into," from in- "into" and currere "run." The prefix is directional, not negative.','e','{}'),
('recur','rih-KUR','v','To happen again or return repeatedly.','It comes back or happens another time.','{"The same methodological error recurs throughout the report.","These doubts recur whenever the evidence is independently examined."}','{"repeat","return"}','{}',22,'From Latin recurrere "run back," from re- "back, again" and currere "run."','e','{}'),
('current','KUR-unt','a','Existing or in use at the present time.','It is happening or accepted now.','{"Current estimates remain substantially lower than the original projections.","The term had a different meaning in current nineteenth-century usage."}','{"present","prevailing"}','{}',22,'From Latin currens, current-, the present participle of currere "run." The sense developed from running or circulating to being in present use.','e','{"A flow of water, air, or electric charge."}'),
('excursion','ik-SKUR-zhun','n','A short journey or departure from a usual course.','It is a brief trip or detour.','{"The essay’s excursion into theology distracts from its central argument.","A coastal excursion offered relief from the exhausting conference."}','{"outing","detour"}','{}',22,'From Latin excursio, from excurrere "run out," composed of ex- and currere, with the action-noun ending -io.','e','{}'),
('incursion','in-KUR-zhun','n','A hostile or unwanted entry into another territory or domain.','Someone pushes into a place where they are not welcome.','{"The border incursion threatened the fragile ceasefire.","Critics opposed the agency’s incursion into local educational policy."}','{"invasion","intrusion"}','{}',22,'From Latin incursio, from incurrere "run into," with in- "into" and currere "run."','e','{}'),
('discursive','dis-KUR-siv','a','Moving from subject to subject rather than following a strict sequence.','It wanders through related topics instead of taking a straight route.','{"The discursive lecture delighted listeners but frustrated meticulous note-takers.","Her discursive style permits illuminating connections between distant subjects."}','{"rambling","digressive"}','{}',22,'From Medieval Latin discursivus, related to Latin discurrere "run about," from dis- "apart" and currere "run," with -ivus.','e','{"Proceeding through reasoning rather than immediate intuition."}'),
('cursive','KUR-siv','a','Written with flowing, connected strokes.','The letters run together instead of standing separately.','{"The archivist deciphered the cramped cursive annotations.","Students compared the cursive signatures on the disputed documents."}','{"flowing","joined"}','{}',21,'From Medieval Latin cursivus, related to Latin currere "run," with -ivus; the handwriting is conceived as running.','e','{}'),
('courier','KUR-ee-er','n','A person or service that delivers messages or packages.','A courier carries something directly to its destination.','{"The courier delivered the confidential dispatch before dawn.","Diplomatic couriers carried documents across the contested border."}','{"messenger","carrier"}','{}',21,'Through French courrier and Italian corriere, ultimately from Latin currere "run."','e','{}'),
('concurrent','kun-KUR-unt','a','Happening at the same time or operating jointly.','Two things are going on together.','{"Concurrent investigations reached sharply different conclusions.","The court imposed concurrent rather than consecutive sentences."}','{"simultaneous","coexisting"}','{"successive","sequential"}',22,'From Latin concurrens, concurrent-, the participle of concurrere "run together," from con- and currere.','e','{}'),
('concurrence','kun-KUR-unss','n','Agreement or simultaneous occurrence.',NULL,'{"The treaty required the concurrence of every participating state.","The concurrence of drought and inflation intensified public discontent."}','{"agreement","coincidence"}','{}',22,'From a French formation related to Latin concurrere "run together," with the abstract ending -ence.','e','{}'),
('recurrence','rih-KUR-unss','n','The return or repeated occurrence of something.','Something that happened before happens again.','{"The revised protocol aims to prevent a recurrence of the error.","The recurrence of this motif gives the novel structural unity."}','{"repetition","return"}','{}',22,'From recur and -ence, ultimately Latin recurrere "run back."','e','{}'),
('discourse','DIS-kors','n','Extended spoken or written discussion of a subject.','It is sustained talk or writing about an issue.','{"Public discourse became less tolerant of ambiguity during the campaign.","The study examines how scientific discourse establishes professional authority."}','{"discussion","conversation"}','{}',22,'From Latin discursus "running about," later discussion, from dis- and currere "run." The English noun continues a Latin action noun, not an English suffix -se.','e','{}'),
('consequence','KON-sih-kwenss','n','A result or effect of an action or condition.','It is what happens because of something else.','{"The policy had an unintended consequence for rural hospitals.","A plausible consequence is not necessarily an inevitable one."}','{"result","outcome"}','{}',22,'From Latin consequentia, from consequi "follow after," composed of con- and sequi "follow."','e','{"Importance or significance."}')
) as v(slug, pr, pos, def, plain, ex, syn, ant, df, ety, es, sec)
on conflict (slug) do nothing;